async function decideManagementCameraPair(id,status){if(!state.room)return;try{await api(`/rooms/${encodeURIComponent(state.room.id)}/management-cameras/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({status})});await refreshManagementCameraPairs()}catch(error){note(`QR카메라 처리 실패: ${error.message}`)}}
