async function managementCameraApi(pairCode,action,options={}){const h=new Headers(options.headers||{});if(state.managementDeviceKey)h.set('x-ekodi-camera-key',state.managementDeviceKey);if(options.body&&!h.has('content-type'))h.set('content-type','application/json');const response=await fetch(`${API}/management-cameras/${encodeURIComponent(pairCode)}/${action}`,{...options,headers:h,cache:'no-store'}),data=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(data.error||`HTTP ${response.status}`);error.status=response.status;throw error}return data}
async function acquireManagementDeviceCamera(){const next=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:state.managementFacing},width:{ideal:1280},height:{ideal:720}},audio:false}),old=state.managementDeviceStream;state.managementDeviceStream=next;const preview=$('managementCameraPreview');if(preview){preview.srcObject=next;preview.play?.().catch(()=>{})}if(state.managementDevicePc){const sender=state.managementDevicePc.getSenders().find(item=>item.track?.kind==='video');if(sender)await sender.replaceTrack(next.getVideoTracks()[0])}old?.getTracks?.().forEach(track=>track.stop());return next}
